M=.next/prerender-manifest.json
[ -f "$M" ] || { echo "SKIP no build artifact; run npm run build first"; exit 77; }
# Routes Next chose to PRERENDER. A page whose render reads the clock and
# does not export force-dynamic appearing here is the finding: its clock was
# frozen at build time.
node -e '
  const m=require("./.next/prerender-manifest.json");
  const pre=Object.keys(m.routes||{}).filter(r=>!r.startsWith("/api"));
  const fs=require("fs");
  const dyn=fs.readdirSync("src/app",{recursive:true})
    .filter(f=>String(f).endsWith("page.tsx"))
    .filter(f=>fs.readFileSync("src/app/"+f,"utf8").includes("force-dynamic"))
    .map(f=>"/"+String(f).replace(/\/?page\.tsx$/,""));
  console.log("prerendered="+JSON.stringify(pre));
  console.log("force-dynamic="+JSON.stringify(dyn));
  // Confirmed when Next prerendered anything the source did not opt out of.
  const leaked=pre.filter(r=>!dyn.includes(r));
  console.log("prerendered-without-optout="+JSON.stringify(leaked));
  process.exit(leaked.length>0?0:1);
'

